#nullable enable

class C
{
    int? M0(object obj) => null;

    void M1(C? c, object? obj)
    {
        int x, y;
        _ = (c?.M0(x = y = 0) == (int?)obj)
            ? x.ToString() // 1
            : y.ToString(); // 2
    }

    void M2(C? c, object? obj)
    {
        int x, y;
        _ = (c?.M0(x = y = 0) == (int?)null)
            ? x.ToString() // 3
            : y.ToString();
    }

    void M3(C? c, object? obj)
    {
        int x, y;
        _ = (c?.M0(x = y = 0) == null)
            ? x.ToString() // 4
            : y.ToString();
    }
}

